/** The unpacked bit field, built once on first use. */
let bits: Uint8Array | null = null;

function field(): Uint8Array {
  if (bits) return bits;
  const bin = typeof atob === "function" ? atob(PACKED) : Buffer.from(PACKED, "base64").toString("binary");
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  bits = out;
  return out;
}

/**
 * True where the given point is over land. Longitude runs from -180 to 180,
 * latitude from 90 (north) to -90.
 */
export function isLand(lon: number, lat: number): boolean {
  const col = Math.floor(((lon + 180) / 360) * LAND_W);
  const row = Math.floor(((90 - lat) / 180) * LAND_H);
  if (row < 0 || row >= LAND_H) return false;
  const c = ((col % LAND_W) + LAND_W) % LAND_W;
  const i = row * LAND_W + c;
  return (((field()[i >> 3] ?? 0) >> (i & 7)) & 1) === 1;
}
